// Find an anchor by its text or selector
final HtmlAnchor link = page.getAnchorByText("Documentation");

// Simulate a real user click - handles JavaScript onclick handlers, relative URLs, and redirects automatically
final HtmlPage targetPage = link.click();

@Test
public void extractOrderedList() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/ordered-list.html");

        // Example: <ol id="orderedList" start="5">
        final HtmlOrderedList list = page.getHtmlElementById("orderedList");

        // Yields:
        // 5. First item
        // 6. Second item
        // Non-item text content
        // 7. Third item
        final String listText = list.asNormalizedText();
    }
}

@Test
public void extractUnorderedList() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/unordered-list.html");

        final HtmlUnorderedList list = page.getHtmlElementById("unorderedList");

        // Yields:
        // First item
        // Second item
        // Non-item text content
        // Third item
        final String listText = list.asNormalizedText();
    }
}

final HtmlOrderedList list = page.getHtmlElementById("orderedList");

for (final DomElement item : list.getElementsByTagName("li")) {
    String itemText = item.asNormalizedText();
    System.out.println("Item: " + itemText);
}

@Test
public void extractInputText() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/login.html");

        // Input field initially defined as: <input type="text" id="username" value="john_doe">
        final HtmlTextInput usernameInput = page.getHtmlElementById("username");

        // Returns the initial visible value: "john_doe"
        final String visibleValue = usernameInput.asNormalizedText();

        // Simulate a user replacing the text in the field
        usernameInput.select();
        usernameInput.type("jane_doe");

        // asNormalizedText() dynamically updates to reflect typed input: "jane_doe"
        final String updatedVisibleValue = usernameInput.asNormalizedText();

        // Enclosing parent elements also reflect the input's updated text
        final String bodyText = page.getBody().asNormalizedText();
    }
}

final HtmlTextInput usernameInput = page.getHtmlElementById("username");

// After typing "jane_doe" into a field with initial attribute value="john_doe":
final String currentVal = usernameInput.getValue();           // "jane_doe"
final String originalAttr = usernameInput.getValueAttribute(); // "john_doe"

@Test
public void extractTextAreaContent() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/feedback.html");

        // <textarea id="comments">
        //   First line
        //   Second line
        //   a <p>html snippet</p>
        // </textarea>
        final HtmlTextArea textArea = page.getHtmlElementById("comments");

        // Returns multiline content with literal HTML tags:
        // "First line\nSecond line\na <p>html snippet</p>\n"
        final String visibleText = textArea.asNormalizedText();

        // Simulate typing new feedback
        textArea.select();
        textArea.type("HtmlUnit makes web automation easy.");

        // Returns the updated user input: "HtmlUnit makes web automation easy."
        final String updatedText = textArea.asNormalizedText();

        // Enclosing page/body text also includes the updated textarea contents
        final String pageText = page.getBody().asNormalizedText();
    }
}

final HtmlTextArea textArea = page.getHtmlElementById("comments");

// Returns the active text content of the textarea
final String content = textArea.getText();

@Test
public void extractInputButtonLabels() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/form.html");

        // <input type="submit" id="defaultSubmit"> -> no value attribute
        final HtmlSubmitInput defaultSubmit = page.getHtmlElementById("defaultSubmit");
        final String submitText = defaultSubmit.asNormalizedText(); // Returns "Submit Query"

        // <input type="reset" id="defaultReset"> -> no value attribute
        final HtmlResetInput defaultReset = page.getHtmlElementById("defaultReset");
        final String resetText = defaultReset.asNormalizedText();   // Returns "Reset"

        // <input type="submit" id="customSubmit" value="Press Me">
        final HtmlSubmitInput customSubmit = page.getHtmlElementById("customSubmit");
        final String customText = customSubmit.asNormalizedText(); // Returns "Press Me"
    }
}

@Test
public void extractButtonText() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/form.html");

        // <button id="actionBtn">  Submit   \n Now </button>
        final HtmlButton button = page.getHtmlElementById("actionBtn");

        // Whitespace is normalized: returns "Submit Now"
        final String buttonLabel = button.asNormalizedText();
    }
}

@Test
public void extractToggleControlState() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final HtmlPage page = webClient.getPage("https://www.example.com/form.html");

        // <input type="checkbox" id="acceptTerms"> Accept terms and conditions
        final HtmlCheckBoxInput checkbox = page.getHtmlElementById("acceptTerms");

        // Returns "unchecked"
        final String initialState = checkbox.asNormalizedText();

        // Enclosing page/form text combines state with adjacent label text:
        // Returns "unchecked Accept terms and conditions"
        final String initialFormText = page.getBody().asNormalizedText();

        // Toggle state programmatically
        checkbox.setChecked(true);

        // asNormalizedText() updates dynamically to "checked"
        final String updatedState = checkbox.asNormalizedText();

        // Enclosing page text now returns: "checked Accept terms and conditions"
        final String updatedFormText = page.getBody().asNormalizedText();
    }
}

final HtmlCheckBoxInput checkbox = page.getHtmlElementById("acceptTerms");
boolean isChecked = checkbox.isChecked(); // returns true or false

final HtmlRadioButtonInput radio = page.getHtmlElementById("optionOne");
boolean isRadioSelected = radio.isChecked();

