final HtmlTable table = page.getHtmlElementById("data-table");
for (final HtmlTableRow row : table.getRows()) {
    for (final HtmlTableCell cell : row.getCells()) {
        System.out.print(cell.asNormalizedText() + "\t");
    }
    System.out.println();
}
